func (s *Store) IndexExternalDir(ctx context.Context, prefix, absDir string) (int, error) {
	info, err := os.Stat(absDir)
	if err != nil || !info.IsDir() {
		return 0, err
	}
	indexedCount := 0
	walkErr := filepath.Walk(absDir, func(path string, fi os.FileInfo, err error) error {
		if err != nil || fi.IsDir() {
			return nil
		}
		if !strings.HasSuffix(strings.ToLower(fi.Name()), ".md") {
			return nil
		}
		// Skip oversized raw monolithic files (>256KB per Rule #21).
		if fi.Size() > 256*1024 {
			return nil
		}
		rel, relErr := filepath.Rel(absDir, path)
		if relErr != nil {
			return nil
		}
		key := prefix + ":" + filepath.ToSlash(rel)
		updated, idxErr := s.IndexAbsoluteFile(ctx, key, path)
		if idxErr == nil && updated {
			indexedCount++
		}
		return nil
	})
	return indexedCount, walkErr

