// concurrently inside a multi-task Wave.
func (tr *TaskRunner) implementBeadWithTask(ctx context.Context, ctxFragment string, st agent.SubTask, useWorktree bool) ([]string, error) {
	tr.setState(PipelineCoding)
	tr.statsMu.Lock()
	if tr.codingStarted.IsZero() {
		tr.codingStarted = time.Now()
	}
	tr.statsMu.Unlock()

	coderCfg := tr.cfg.Agents[string(bus.RoleCoder)]
	routedModel := coderCfg.ResolveModelForComplexity(st.Complexity)
	if routedModel != "" && routedModel != coderCfg.Model {
		tr.event(fmt.Sprintf("dynamic model routing [%s]: complexity=%s → model=%s", st.Key, st.Complexity, routedModel))
	}

	worktreeDir := ""
	var gc *gitclient.GitClient
	if useWorktree {
		gc = gitclient.New(tr.root)
		wtDir := filepath.Join(os.TempDir(), fmt.Sprintf("orch-wt-%s-%s-%d", tr.runID, st.Key, time.Now().UnixNano()))
		if err := gc.WorktreeAdd(wtDir, ""); err == nil {
			worktreeDir = wtDir
			defer func() { _ = gc.WorktreeRemove(wtDir) }()
		}
	}

	resp, err := tr.runAgent(ctx, bus.RoleCoder, agent.CoderPayload{
		Plan:           st.Title + "\n\n" + st.Description,
		ProjectContext: ctxFragment,
		StageName:      st.Title,
		StageIndex:     st.Wave + 1,
		TotalStages:    1,
		ModelOverride:  routedModel,
		WorktreeRoot:   worktreeDir,
	})
	if err != nil {
		return nil, fmt.Errorf("coder: %w", err)
	}
	files := extractCoderResult(resp).Files
	if worktreeDir != "" && gc != nil && len(files) > 0 {
		tr.statsMu.Lock()
		syncErr := gc.SyncWorktreeFiles(worktreeDir, files)
		tr.statsMu.Unlock()
		if syncErr != nil {
			return nil, fmt.Errorf("sync worktree %s: %w", st.Key, syncErr)

